#!/usr/bin/env bash
set -euo pipefail

link_if_present() {
    if [[ -e "$1" ]]; then
        ln -sfn "$1" "/usr/local/bin/$2"
    fi
}

# Familiar names for commands packaged under other names.
link_if_present /usr/local/bin/oc kubectl
link_if_present /usr/bin/fdfind fd
link_if_present /usr/bin/batcat bat
link_if_present /usr/bin/vim.tiny vim

for dir in /opt/python/3.*; do
    minor=${dir##*/}
    ln -sfn "$dir/bin/python$minor" "/usr/local/bin/python$minor"
done

# Shell setup, including completions generated by the installed versions themselves.
printf '\n[ -r /opt/toolbox/share/bashrc ] && . /opt/toolbox/share/bashrc\n' >>/etc/bash.bashrc
if [[ -f /etc/zsh/zshrc ]]; then
    printf '\n[ -r /opt/toolbox/share/zshrc ] && . /opt/toolbox/share/zshrc\n' >>/etc/zsh/zshrc
fi

completion_home=$(mktemp -d)
completion() {
    local name=$1
    shift
    if command -v "$name" >/dev/null; then
        HOME=$completion_home "$@" >"/usr/share/bash-completion/completions/$name"
    fi
}
completion oc oc completion bash
completion kubectl kubectl completion bash
completion helm helm completion bash
completion kustomize kustomize completion bash
completion argocd argocd completion bash
completion k9s k9s completion bash
completion stern stern --completion bash
completion gh gh completion -s bash
completion uv uv generate-shell-completion bash
completion yq yq completion bash
completion crane crane completion bash
completion oras oras completion bash
completion cosign cosign completion bash
rm -rf "$completion_home"

# Group 0 ownership lets the arbitrary UIDs OpenShift assigns write to these two directories.
useradd --uid 1001 --gid 0 --no-log-init --create-home --home-dir /home/toolbox --shell /bin/bash toolbox
chmod -R g=u /home/toolbox
install -d -o 1001 -g 0 -m 0775 /workspace

python3 /build/write-manifest.py /opt/toolbox/share/manifest.json /build/tools.lock /build/go-tools.lock

chmod -R a+rX /opt
find / -xdev -type f -perm /6000 -exec chmod a-s {} + 2>/dev/null || true
rm -rf /root/.cache /root/.config /root/.local /tmp/* /var/tmp/*

# Image scanners reject an image that contains a private key, even one from a package's test fixtures.
# Fails here so the file is removed where it is installed; deleting it in this layer would leave it in
# the layer below. Only text files are read: compiled programs are left to the scanners.
private_keys=$(find / -xdev -type f -print0 |
    xargs -0 grep -lIE '^-----BEGIN ([A-Z0-9]+ )*PRIVATE KEY( BLOCK)?-----[[:space:]]*$' 2>/dev/null || true)
if [[ -n "$private_keys" ]]; then
    printf 'Private keys found in the image:\n%s\n' "$private_keys" >&2
    exit 1
fi
